package com.edufun.portal.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="exam_sessions") public class ExamSession { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String title; private String level; private String subject; private LocalDateTime startsAt; private LocalDateTime endsAt; private LocalDateTime correctionDueAt; private LocalDateTime resultPublishedAt; private String status="SCHEDULED"; public Long getId(){return id;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getLevel(){return level;} public void setLevel(String v){level=v;} public String getSubject(){return subject;} public void setSubject(String v){subject=v;} public LocalDateTime getStartsAt(){return startsAt;} public void setStartsAt(LocalDateTime v){startsAt=v;} public LocalDateTime getEndsAt(){return endsAt;} public void setEndsAt(LocalDateTime v){endsAt=v;} public LocalDateTime getCorrectionDueAt(){return correctionDueAt;} public void setCorrectionDueAt(LocalDateTime v){correctionDueAt=v;} public LocalDateTime getResultPublishedAt(){return resultPublishedAt;} public void setResultPublishedAt(LocalDateTime v){resultPublishedAt=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }
